onent_Terminal({lines:[({command:"wf assets",output:""}),({command:"wf assets --unused",output:""}),({command:"wf assets --plan /hero.png",output:""}),({command:"wf assets --json",output:""})]});_e15489.appendChild(_e16244);const _e16245=WF.el("div",{className:"wf-markdown",markdown:"For each file it prints its kind (image, font, video, audio, document, code, data), its size, a picture's dimensions, and every place the project names it: a prop the registry types as a file (`Image`'s `src`, `Video`'s `poster` and `captions`), a page's `image:`, a `const`, an `image` declaration, a `data` file's strings, a value in `webfluent.app.json`, a stylesheet's `url(…)`, a project script, or a manifest. A file a browser or a host asks for by name — `favicon.ico`, `robots.txt`, `.well-known/…` — counts as used. Anything else nothing names counts as unused.\n\n`--plan PATH` applies the project's `build.media` to one picture: each width it writes, in each format, with the file's name and size — for example *3 widths × 1 format · 3 files · about 84 kB*. A size is exact once `wf build` has written the file (it is read from `.wf-cache/media/`), or when the picture is small enough to encode on the spot. Otherwise it is estimated from strips of the picture encoded at that width, and says `about`. The plan names a format the build cannot write, with the reason, and a width it skips because the file would be no smaller than the original. With `--json`, the same sentences are in the `said` field.\n\nThe library has the same as `webfluent::build::assets::{list, plan}`. It reads through a `Vfs`, so an editor's unsaved buffers count.\n\nSee also: [Add a picture](/recipes/add-a-picture)."});_e15489.appendChild(_e16245);const _e16246=WF.el("h3",{className:"wf-heading",id:"wf-theme"},"wf theme");_e15489.appendChild(_e16246);const _e16247=WF.el("div",{className:"wf-markdown",markdown:"Shows the theme the build uses, as an editor's theme panel shows it.\n\n**Usage:** `wf theme [OPTIONS]`"});_e154